container_default_user_device_open.command:
env DOCKER_API_VERSION=1.43 docker exec -e CUDA_VISIBLE_DEVICES=GPU-528f4e79-58c0-e843-bf5e-0b40c2671cd7 -w <workspace>/torch-learn pytorch-dev-gpu67 python -c 'import os,json,ctypes
paths=["/dev/nvidiactl","/dev/nvidia-uvm","/dev/nvidia6","/dev/nvidia7"]
result={"uid":os.getuid(),"gid":os.getgid(),"nodes":[]}
for p in paths:
 st=os.stat(p); item={"path":p,"mode":oct(st.st_mode&0o777),"uid":st.st_uid,"gid":st.st_gid,"major":os.major(st.st_rdev),"minor":os.minor(st.st_rdev)}
 try:
  fd=os.open(p,os.O_RDWR); os.close(fd); item["open"]="OK"
 except OSError as e: item.update(errno=e.errno,error=e.strerror)
 result["nodes"].append(item)
drv=ctypes.CDLL("libcuda.so.1"); result["cuInit"]=drv.cuInit(0)
print(json.dumps(result,indent=2))
'

